package com.duckblade.osrs.pot;

import java.io.IOException;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.sound.sampled.LineUnavailableException;
import javax.sound.sampled.UnsupportedAudioFileException;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.SoundEffectVolume;
import net.runelite.client.Notifier;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.util.Filepath;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class NotificationManager
{

	private static final String CUSTOM_SOUND_FILE_NAME = "notification.wav";

	private final Client client;
	private final PotNotifierConfig config;
	private final Notifier notifier;
	private final AudioPlayer audioPlayer;
	private final ScheduledExecutorService executor;

	private volatile Filepath customSoundFile;

	public void startUp(Filepath dataDir) throws IOException
	{
		customSoundFile = null;
		dataDir.createDirectories();
		customSoundFile = dataDir.joinSegment(CUSTOM_SOUND_FILE_NAME);
	}

	public void notifyPotted(Player p)
	{
		notifier.notify(config.notificationRuneLite(), p.getName() + " has potted!");

		if (config.soundEffectEnabled())
		{
			playInGameSound();
		}

		if (config.customSoundEnabled())
		{
			playCustomSound();
		}
	}

	private void playInGameSound()
	{
		// config is a 1-100 percentage, the game's sound effect volume is 0-127
		int volume = Math.round(config.soundEffectVolume() * SoundEffectVolume.HIGH / 100f);
		client.playSoundEffect(config.soundEffectId(), volume);
	}

	private void playCustomSound()
	{
		Filepath file = customSoundFile;
		int volume = config.customSoundVolume();
		if (file == null || volume <= 0)
		{
			return;
		}

		float gainDb = (float) Math.log10(volume / 100f) * 20;
		executor.submit(() ->
		{
			if (!file.isFile())
			{
				log.debug("custom sound file {} does not exist", file);
				return;
			}

			try
			{
				audioPlayer.play(file, gainDb);
			}
			catch (Exception e)
			{
				log.warn("Failed to play custom sound {}", file, e);
			}
		});
	}

}

package com.duckblade.osrs.pot;

import net.runelite.api.gameval.SoundEffectID;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Notification;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup("potnotifier")
public interface PotNotifierConfig extends Config
{

	@ConfigSection(
		name = "Locations",
		description = "Where to notify when a teammate pots.",
		position = 0
	)
	String SECTION_LOCATIONS = "locations";

	@ConfigSection(
		name = "Notifications",
		description = "How to notify when a teammate pots.",
		position = 1
	)
	String SECTION_NOTIFICATIONS = "notifications";

	@ConfigItem(
		keyName = "locationCox",
		name = "CoX",
		description = "Notify in the Chambers of Xeric.",
		section = SECTION_LOCATIONS,
		position = 0
	)
	default boolean locationCox()
	{
		return true;
	}

	@ConfigItem(
		keyName = "locationTob",
		name = "ToB",
		description = "Notify in the Theatre of Blood.",
		section = SECTION_LOCATIONS,
		position = 1
	)
	default boolean locationTob()
	{
		return true;
	}

	@ConfigItem(
		keyName = "locationToa",
		name = "ToA",
		description = "Notify in the Tombs of Amascut.",
		section = SECTION_LOCATIONS,
		position = 2
	)
	default boolean locationToa()
	{
		return true;
	}

	@ConfigItem(
		keyName = "locationTfa",
		name = "TFA",
		description = "Notify in The Fractured Archive.",
		section = SECTION_LOCATIONS,
		position = 3
	)
	default boolean locationTfa()
	{
		return true;
	}

	@ConfigItem(
		keyName = "locationNex",
		name = "Nex",
		description = "Notify at Nex.",
		section = SECTION_LOCATIONS,
		position = 4
	)
	default boolean locationNex()
	{
		return true;
	}

	@ConfigItem(
		keyName = "notificationRuneLite",
		name = "RuneLite Notification",
		description = "Send a RuneLite notification when a teammate pots.",
		section = SECTION_NOTIFICATIONS,
		position = 0
	)
	default Notification notificationRuneLite()
	{
		return Notification.OFF;
	}

	@ConfigItem(
		keyName = "soundEffectEnabled",
		name = "In-Game Sound Effect",
		description = "Play an in-game sound effect when a teammate pots.",
		section = SECTION_NOTIFICATIONS,
		position = 1
	)
	default boolean soundEffectEnabled()
	{
		return true;
	}

	@ConfigItem(
		keyName = "soundEffectId",
		name = " ↳ Sound Effect ID",
		description = "The in-game sound effect ID to play.",
		section = SECTION_NOTIFICATIONS,
		position = 2
	)
	@Range(min = 0)
	default int soundEffectId()
	{
		return SoundEffectID.JEWEL_DING;
	}

	@ConfigItem(
		keyName = "soundEffectVolume",
		name = " ↳ Volume",
		description = "The volume of the in-game sound effect.",
		section = SECTION_NOTIFICATIONS,
		position = 3
	)
	@Units(Units.PERCENT)
	@Range(min = 1, max = 100)
	default int soundEffectVolume()
	{
		return 50;
	}

	@ConfigItem(
		keyName = "customSoundEnabled",
		name = "Custom Sound",
		description = "Play a custom sound when a teammate pots." +
			"<br>Place a WAV file named notification.wav in .runelite/plugin-data/pot-notifier for it to play.",
		section = SECTION_NOTIFICATIONS,
		position = 4
	)
	default boolean customSoundEnabled()
	{
		return false;
	}

	@ConfigItem(
		keyName = "customSoundVolume",
		name = " ↳ Volume",
		description = "The volume of the custom sound.",
		section = SECTION_NOTIFICATIONS,
		position = 5
	)
	@Units(Units.PERCENT)
	@Range(min = 1, max = 100)
	default int customSoundVolume()
	{
		return 50;
	}
}

package com.duckblade.osrs.pot;

import com.duckblade.osrs.pot.location.CoxLocationCheck;
import com.duckblade.osrs.pot.location.LocationCheck;
import com.duckblade.osrs.pot.location.NexLocationCheck;
import com.duckblade.osrs.pot.location.TfaLocationCheck;
import com.duckblade.osrs.pot.location.ToaLocationCheck;
import com.duckblade.osrs.pot.location.TobLocationCheck;
import com.google.common.collect.ImmutableList;
import com.google.inject.Provides;
import java.io.IOException;
import java.util.List;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.SpotanimID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "Pot Notifier",
	internalName = "pot-notifier",
	description = "Notifies you when your teammates pot.",
	tags = {"pot", "potion", "chug", "chugging", "barrel", "ready"}
)
public class PotNotifierPlugin extends Plugin
{

	private static final int COOLDOWN_TICKS = 50;

	@Inject
	private Client client;

	@Inject
	private PotNotifierConfig config;

	@Inject
	private CoxLocationCheck coxLocationCheck;

	@Inject
	private TobLocationCheck tobLocationCheck;

	@Inject
	private ToaLocationCheck toaLocationCheck;

	@Inject
	private TfaLocationCheck tfaLocationCheck;

	@Inject
	private NexLocationCheck nexLocationCheck;

	@Inject
	private NotificationManager notificationManager;

	private int lastLocalPot = Integer.MIN_VALUE;
	private int lastNotify = Integer.MIN_VALUE;
	private List<LocationCheck> locationChecks;

	@Provides
	PotNotifierConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PotNotifierConfig.class);
	}

	@Override
	protected void startUp()
	{
		locationChecks = ImmutableList.of(
			coxLocationCheck,
			tobLocationCheck,
			toaLocationCheck,
			tfaLocationCheck,
			nexLocationCheck
		);

		reset();

		try
		{
			notificationManager.startUp(getPluginDirectory());
		}
		catch (IOException e)
		{
			log.warn("Failed to create plugin data directory, custom sounds are unavailable", e);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		GameState state = e.getGameState();
		if (state == GameState.LOGGING_IN || state == GameState.HOPPING)
		{
			reset();
		}
	}

	private void reset()
	{
		lastLocalPot = Integer.MIN_VALUE;
		lastNotify = Integer.MIN_VALUE;
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged e)
	{
		int now = client.getTickCount();
		if (now < lastLocalPot + COOLDOWN_TICKS || now < lastNotify + COOLDOWN_TICKS)
		{
			return;
		}

		if (!(e.getActor() instanceof Player))
		{
			return;
		}

		int regionId = WorldPoint.fromLocalInstance(client, client.getLocalPlayer().getLocalLocation()).getRegionID();
		LocationCheck location = resolveLocationCheck(regionId);
		if (location == null)
		{
			return;
		}

		Player p = (Player) e.getActor();
		if (!playerIsPotting(p))
		{
			return;
		}

		if (p == client.getLocalPlayer())
		{
			lastLocalPot = now;
			return;
		}

		if (location.isPlayerOfInterest(p))
		{
			lastNotify = now;
			notificationManager.notifyPotted(p);
		}
	}

	private LocationCheck resolveLocationCheck(int regionId)
	{
		for (LocationCheck check : locationChecks)
		{
			if (check.isInRegion(regionId) && check.isEnabled(config))
			{
				return check;
			}
		}

		return null;
	}

	private boolean playerIsPotting(Player p)
	{
		if (p.getAnimation() == AnimationID.PREPOT_DEVICE_DRINK_FULL)
		{
			return true;
		}

		return p.getAnimation() == AnimationID.HUMAN_EAT &&
			p.hasSpotAnim(SpotanimID.SKELETON_KILLERWATT_ELECTRICSHOCK);
	}
}

package com.duckblade.osrs.pot.location;

import com.duckblade.osrs.pot.PotNotifierConfig;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.FriendsChatManager;
import net.runelite.api.Player;
import net.runelite.client.util.Text;

@Singleton
public class CoxLocationCheck
	implements LocationCheck
{

	@Inject
	private Client client;

	@Override
	public boolean isEnabled(PotNotifierConfig config)
	{
		return config.locationCox();
	}

	@Override
	public boolean isInRegion(int regionId)
	{
		switch (regionId)
		{
			case 4919: // outside
			case 13393: // inside cox variant 1
			case 13137: // inside cox variant 2
				return true;

			default:
				return false;
		}
	}

	@Override
	public boolean isPlayerOfInterest(Player p)
	{
		// everyone inside a raid instance is on the local player's team
		if (client.getTopLevelWorldView().isInstance())
		{
			return true;
		}

		// otherwise (e.g. the lobby), only the local friends chat counts
		FriendsChatManager friendsChat = client.getFriendsChatManager();
		String name = p.getName();
		return friendsChat != null &&
			name != null &&
			friendsChat.findByName(Text.removeTags(name)) != null;
	}

}

package com.duckblade.osrs.pot.location;

import com.duckblade.osrs.pot.PotNotifierConfig;
import net.runelite.api.Player;

public interface LocationCheck
{

	/**
	 * @return whether notifications are enabled for this location in the config
	 */
	boolean isEnabled(PotNotifierConfig config);

	/**
	 * @param regionId the region of the local player
	 * @return whether the region is part of this location
	 */
	boolean isInRegion(int regionId);

	/**
	 * @return whether the given player is someone we want to be notified about, e.g. in our raid party
	 */
	default boolean isPlayerOfInterest(Player p)
	{
		return true;
	}

}

